#!/bin/bash
# QA completo: intro -> lab -> Rota 1 -> Harvestvale -> transicoes -> Cap. 1 -> Cap. 2 -> Route 2 -> Route 3 -> Cap. 3 (Ferralia). Uso: qa_completo.sh RUNNER WORKDIR
set -e -o pipefail
ROOT=$(cd "$(dirname "$0")/../.." && pwd); R=$1; W=$2; mkdir -p "$W"
SB1=$(awk '$2=="gSaveBlock1Ptr" && $1 ~ /^0x03/ {print substr($1,3); exit}' "$ROOT/pokeemerald.map")
{ cat "$ROOT/tools/hollowtide_qa/roteiros/01_intro_ate_casa.txt"; echo pos; echo "expect_map 1 0"; echo "savestate $W/casa.ss"; } > "$W/intro.txt"
"$R" "$ROOT/pokeemerald.gba" "$W/intro.txt" - "$SB1" | grep -E "^ *(OK|FALHA)|RESUMO|Traceback|Error|FLUXO"
python3 -I "$ROOT/tools/hollowtide_qa/fluxo_inicial.py" "$ROOT/pokeemerald.gba" "$R" "$W" "$W/casa.ss" | grep -E "^ *(OK|FALHA)|RESUMO|Traceback|Error|FLUXO"
python3 -I "$ROOT/tools/hollowtide_qa/fluxo_transicoes.py" "$ROOT/pokeemerald.gba" "$R" "$W" "$W/e2e_colheita.ss" | grep -E "^ *(OK|FALHA)|RESUMO|Traceback|Error|FLUXO"
